@@ -0,0 +1,354 @@
+// Anthropic Messages data plane: `/v1/messages` and
+// `/v1/messages/count_tokens`, as `entrypoints/anthropic/protocol.py`
+// declares them (mirroring anthropic-sdk-python). The server translates onto
+// the chat path; shared by the HTTP adapter, the gRPC service, and the router.
+syntax = "proto3";
+
+package sglang.api.v1;
+
+import "sglang/api/v1/common.proto";
+import "sglang/json/v1/options.proto";
+
+// ---- Errors ----------------------------------------------------------------
+
+// `error.type` is one of Anthropic's documented values (invalid_request_error,
+// authentication_error, permission_error, not_found_error, request_too_large,
+// rate_limit_error, api_error, overloaded_error); strict SDK clients parse it.
+message AnthropicError {
+  string type = 1;
+  string message = 2;
+}
+
+// The HTTP error envelope: `{"type": "error", "error": {...}}`.
+message AnthropicErrorResponse {
+  string type = 1;
+  AnthropicError error = 2;
+}
+
+// ---- Usage -----------------------------------------------------------------
+
+// `input_tokens` excludes cached prompt tokens, which go to
+// `cache_read_input_tokens`. A streamed `message_delta` carries only
+// `output_tokens`; `message_start` and the unary reply carry both.
+message AnthropicUsage {
+  optional int64 input_tokens = 1;
+  optional int64 output_tokens = 2;
+  optional int64 cache_creation_input_tokens = 3;
+  optional int64 cache_read_input_tokens = 4;
+}
+
+// ---- Content blocks (tagged by `type`) ---------------------------------------
+
+message AnthropicContentBlock {
+  oneof block {
+    option (sglang.json.v1.oneof_json).shape = ONEOF_SHAPE_TAGGED;
+    option (sglang.json.v1.oneof_json).tag = "type";
+    AnthropicTextBlock text = 1;
+    AnthropicImageBlock image = 2;
+    AnthropicToolUseBlock tool_use = 3;
+    AnthropicToolResultBlock tool_result = 4;
+    AnthropicToolReferenceBlock tool_reference = 5;
+    AnthropicSearchResultBlock search_result = 6;
+    AnthropicThinkingBlock thinking = 7;
+    AnthropicRedactedThinkingBlock redacted_thinking = 8;
+  }
+}
+
+message AnthropicContentBlockList {
+  option (sglang.json.v1.message_json).shape = MESSAGE_SHAPE_BARE_LIST;
+  repeated AnthropicContentBlock items = 1;
+}
+
+// A message's `content` and the request `system`: a string or a block list.
+message AnthropicContent {
+  oneof value {
+    option (sglang.json.v1.oneof_json).shape = ONEOF_SHAPE_UNTAGGED;
+    string text = 1;
+    AnthropicContentBlockList blocks = 2;
+  }
+}
+
+message AnthropicTextBlock {
+  string text = 1;
+}
+
+// `source` is `{"type": "base64", "media_type", "data"}` or `{"url"}`; a bare
+// string is accepted and ignored, as in Python.
+message AnthropicImageBlock {
+  optional AnthropicImageSource source = 1;
+}
+
+message AnthropicImageSource {
+  oneof value {
+    option (sglang.json.v1.oneof_json).shape = ONEOF_SHAPE_UNTAGGED;
+    string reference = 1;
+    AnthropicImageSourceObject object = 2;
+  }
+}
+
+message AnthropicImageSourceObject {
+  optional string type = 1;
+  optional string media_type = 2;
+  optional string data = 3;
+  optional string url = 4;
+}
+
+// The tool arguments object, passed through as JSON text.
+message AnthropicToolUseBlock {
+  string id = 1;
+  string name = 2;
+  optional string input = 3 [(sglang.json.v1.field_json).raw_json = true];
+}
+
+// `tool_use_id` per the spec; legacy payloads send `id` instead.
+message AnthropicToolResultBlock {
+  optional string tool_use_id = 1;
+  optional string id = 2;
+  optional AnthropicContent content = 3;
+  optional bool is_error = 4;
+}
+
+// SGLang extension: names a deferred-loaded tool (`tool_name` or `name`).
+message AnthropicToolReferenceBlock {
+  optional string name = 1;
+  optional string tool_name = 2;
+  optional string id = 3;
+}
+
+message AnthropicSearchResultBlock {
+  optional AnthropicSearchSource source = 1;
+  optional string title = 2;
+  repeated AnthropicSearchResultItem content = 3;
+}
+
+// A URL / identifier string, or an object with `url` or `text`.
+message AnthropicSearchSource {
+  oneof value {
+    option (sglang.json.v1.oneof_json).shape = ONEOF_SHAPE_UNTAGGED;
+    string reference = 1;
+    AnthropicSearchSourceObject object = 2;
+  }
+}
+
+message AnthropicSearchSourceObject {
+  optional string url = 1;
+  optional string text = 2;
+}
+
+// Only `type: "text"` items are read.
+message AnthropicSearchResultItem {
+  optional string type = 1;
+  optional string text = 2;
+}
+
+// `signature` is omitted when the backend has none; an empty string would
+// fail downstream signature verifiers.
+message AnthropicThinkingBlock {
+  string thinking = 1;
+  optional string signature = 2;
+}
+
+message AnthropicRedactedThinkingBlock {
+  optional string data = 1;
+}
+
+// ---- Messages, tools, controls -----------------------------------------------
+
+// `role` is "user", "assistant", or "system".
+message AnthropicMessage {
+  string role = 1;
+  AnthropicContent content = 2;
+}
+
+// One flat shape for every tool family. A custom tool has no `type` (or
+// "custom") and an `input_schema`; the server tools (`web_search_*`,
+// `computer_*`, `bash_*`, `text_editor_*`) carry their own knobs and are
+// skipped by the server, which has no implementation for them.
+message AnthropicTool {
+  optional string type = 1;
+  string name = 2;
+  optional string description = 3;
+  // The JSON Schema of the arguments; `{"type": "object"}` is filled when the
+  // schema has no `type`.
+  optional string input_schema = 4 [(sglang.json.v1.field_json).raw_json = true];
+  optional bool defer_loading = 5;
+  optional int64 max_uses = 6;
+  repeated string allowed_domains = 7;
+  repeated string blocked_domains = 8;
+  optional int64 display_width_px = 9;
+  optional int64 display_height_px = 10;
+  optional int64 display_number = 11;
+}
+
+// `type` is "auto", "any", "tool" (with `name`), or "none".
+message AnthropicToolChoice {
+  string type = 1;
+  optional string name = 2;
+}
+
+// `type` is "enabled" (`budget_tokens` >= 1024 required), "disabled" (no
+// other field), or "adaptive" (no `budget_tokens`). The budget is accepted
+// and not enforced; `display` "omitted" cannot hide reasoning here.
+message AnthropicThinkingParam {
+  string type = 1;
+  optional int64 budget_tokens = 2;
+  optional string display = 3;
+}
+
+// A soft hint; `max_tokens` stays the hard cap.
+message AnthropicTaskBudget {
+  string type = 1;
+  int64 total = 2;
+  optional int64 remaining = 3;
+}
+
+// `effort` is "minimal" | "low" | "medium" | "high" | "xhigh" | "max".
+message AnthropicOutputConfig {
+  optional string effort = 1;
+  optional AnthropicTaskBudget task_budget = 2;
+}
+
+// `POST /v1/messages`. The routing fields are the P/D and DP hints a router
+// may inject, as on the OpenAI routes.
+message AnthropicMessagesRequest {
+  string model = 1;
+  repeated AnthropicMessage messages = 2;
+  int64 max_tokens = 3;
+  // Opaque client metadata; accepted and ignored.
+  optional string metadata = 4 [(sglang.json.v1.field_json).raw_json = true];
+  repeated string stop_sequences = 5;
+  optional bool stream = 6 [
+    (sglang.json.v1.field_json).null_policy = NULL_POLICY_RESETS_DEFAULT,
+    (sglang.json.v1.field_json).default_bool = false
+  ];
+  optional AnthropicContent system = 7;
+  optional double temperature = 8;
+  optional AnthropicThinkingParam thinking = 9;
+  optional AnthropicToolChoice tool_choice = 10;
+  repeated AnthropicTool tools = 11;
+  optional int64 top_k = 12;
+  optional double top_p = 13;
+  optional AnthropicOutputConfig output_config = 14;
+  // SDK beta opt-ins; accepted and ignored.
+  repeated string betas = 15;
+  optional StringOrList bootstrap_host = 16;
+  optional OptionalInt64OrList bootstrap_port = 17;
+  optional Int64OrList bootstrap_room = 18;
+  optional int64 routed_dp_rank = 19;
+  optional int64 disagg_prefill_dp_rank = 20;
+}
+
+// The unary reply, and the `message` of a streamed `message_start` (where
+// `content` is empty and `output_tokens` 0). `stop_reason` is "end_turn",
+// "max_tokens", "stop_sequence", or "tool_use".
+message AnthropicMessagesResponse {
+  string id = 1;
+  string type = 2;
+  string role = 3;
+  AnthropicContentBlockList content = 4;
+  string model = 5;
+  optional string stop_reason = 6;
+  optional string stop_sequence = 7;
+  optional AnthropicUsage usage = 8;
+}
+
+// `POST /v1/messages/count_tokens`: the rendered prompt's token count.
+message AnthropicCountTokensRequest {
+  string model = 1;
+  repeated AnthropicMessage messages = 2;
+  optional AnthropicContent system = 3;
+  optional AnthropicThinkingParam thinking = 4;
+  optional AnthropicToolChoice tool_choice = 5;
+  repeated AnthropicTool tools = 6;
+  optional AnthropicOutputConfig output_config = 7;
+  repeated string betas = 8;
+}
+
+message AnthropicCountTokensResponse {
+  int64 input_tokens = 1;
+}
+
+// ---- Stream events (tagged by `type`) ----------------------------------------
+
+// One SSE event of a streamed `/v1/messages`; the SSE `event:` name is the
+// tag. The sequence is message_start, then content_block_start / delta /
+// stop groups, then message_delta and message_stop; a failure closes any
+// open block, then emits error and message_stop.
+message AnthropicStreamEvent {
+  oneof event {
+    option (sglang.json.v1.oneof_json).shape = ONEOF_SHAPE_TAGGED;
+    option (sglang.json.v1.oneof_json).tag = "type";
+    AnthropicMessageStartEvent message_start = 1;
+    AnthropicMessageDeltaEvent message_delta = 2;
+    AnthropicMessageStopEvent message_stop = 3;
+    AnthropicContentBlockStartEvent content_block_start = 4;
+    AnthropicContentBlockDeltaEvent content_block_delta = 5;
+    AnthropicContentBlockStopEvent content_block_stop = 6;
+    AnthropicPingEvent ping = 7;
+    AnthropicErrorEvent error = 8;
+  }
+}
+
+message AnthropicMessageStartEvent {
+  AnthropicMessagesResponse message = 1;
+}
+
+message AnthropicMessageDeltaEvent {
+  AnthropicMessageEndDelta delta = 1;
+  AnthropicUsage usage = 2;
+}
+
+// No `type` inside: the event name already says message_delta.
+message AnthropicMessageEndDelta {
+  optional string stop_reason = 1;
+  optional string stop_sequence = 2;
+}
+
+message AnthropicMessageStopEvent {}
+
+message AnthropicContentBlockStartEvent {
+  int64 index = 1;
+  AnthropicContentBlock content_block = 2;
+}
+
+message AnthropicContentBlockDeltaEvent {
+  int64 index = 1;
+  AnthropicContentDelta delta = 2;
+}
+
+message AnthropicContentBlockStopEvent {
+  int64 index = 1;
+}
+
+message AnthropicPingEvent {}
+
+message AnthropicErrorEvent {
+  AnthropicError error = 1;
+}
+
+message AnthropicContentDelta {
+  oneof delta {
+    option (sglang.json.v1.oneof_json).shape = ONEOF_SHAPE_TAGGED;
+    option (sglang.json.v1.oneof_json).tag = "type";
+    AnthropicTextDelta text_delta = 1;
+    AnthropicInputJsonDelta input_json_delta = 2;
+    AnthropicThinkingDelta thinking_delta = 3;
+    AnthropicSignatureDelta signature_delta = 4;
+  }
+}
+
+message AnthropicTextDelta {
+  string text = 1;
+}
+
+message AnthropicInputJsonDelta {
+  string partial_json = 1;
+}
+
+message AnthropicThinkingDelta {
+  string thinking = 1;
+}
+
+message AnthropicSignatureDelta {
+  string signature = 1;
+}

@@ -107,6 +107,17 @@ message OptionalStringList {
   repeated OptionalString items = 1;
 }

+// A nullable double list element (e.g. a completion token logprob).
+message OptionalDouble {
+  option (sglang.json.v1.message_json).shape = MESSAGE_SHAPE_TRANSPARENT;
+  optional double value = 1;
+}
+
+message DoubleList {
+  option (sglang.json.v1.message_json).shape = MESSAGE_SHAPE_BARE_LIST;
+  repeated double items = 1;
+}
+
 message OptionalInt64 {
   option (sglang.json.v1.message_json).shape = MESSAGE_SHAPE_TRANSPARENT;
   optional int64 value = 1;

@@ -0,0 +1,143 @@
+// Scheduler control APIs shared by HTTP JSON and gRPC: one request per
+// operation, fanned out to every DP rank by the Rust frontend, with the
+// per-rank replies merged the way the Python TokenizerManager merges them.
+syntax = "proto3";
+
+package sglang.api.v1;
+
+import "sglang/api/v1/common.proto";
+import "sglang/json/v1/options.proto";
+
+// `/set_internal_state`: numeric scheduler knobs to override at runtime.
+message SetInternalStateRequest {
+  // Python's `SetInternalStateReq.server_args: Dict[str, int | float]`. The
+  // key set is the scheduler's (`Scheduler.set_internal_state` rejects
+  // unknown keys), so the object passes through as JSON text.
+  optional string server_args = 1 [(sglang.json.v1.field_json).raw_json = true];
+}
+
+// One `updated` flag per DP rank, in rank order; Python's `List[bool]`.
+message SetInternalStateResponse {
+  option (sglang.json.v1.message_json).shape = MESSAGE_SHAPE_BARE_LIST;
+  repeated bool updated = 1;
+}
+
+// `/start_profile`: begin a profiler capture on every DP rank. Python's
+// `ProfileReq` minus `req_type`, which the operation implies. The frontend
+// fills `with_stack`/`record_shapes` from `SGLANG_PROFILE_WITH_STACK` /
+// `SGLANG_PROFILE_RECORD_SHAPES` when unset and mints `profile_id` when
+// absent, as Python's TokenizerManager does.
+message StartProfileRequest {
+  optional string output_dir = 1;
+  optional int64 start_step = 2;
+  // Stop automatically after this many steps; no `/stop_profile` needed.
+  optional int64 num_steps = 3;
+  // Among "CPU", "GPU", "MEM", "RPD"; the scheduler's default when unset.
+  optional StringList activities = 4;
+  bool profile_by_stage = 5;
+  optional bool with_stack = 6;
+  optional bool record_shapes = 7;
+  optional string profile_id = 8;
+  bool merge_profiles = 9;
+  optional string profile_prefix = 10;
+  optional StringList profile_stages = 11;
+  bool detailed_annotations = 12;
+}
+
+message StopProfileRequest {}
+
+// The merged outcome of a profile start or stop across DP ranks.
+message ProfileResponse {
+  bool success = 1;
+  string message = 2;
+}
+
+// `/start_expert_distribution_record`, `/stop_expert_distribution_record`,
+// `/dump_expert_distribution_record`: the MoE expert-distribution recorder
+// on every DP rank. The operation implies the action.
+message ExpertDistributionRecordRequest {}
+message ExpertDistributionRecordResponse {}
+
+// `/slow_down`: sleep this long before every forward, for testing; unset or
+// non-positive clears the delay.
+message SlowDownRequest {
+  optional double forward_sleep_time = 1;
+}
+message SlowDownResponse {}
+
+// `/release_memory_occupation` and `/resume_memory_occupation`: free or
+// reclaim the GPU memory of the tagged regions (`weights`, `kv_cache`); every
+// region when `tags` is unset.
+message ReleaseMemoryOccupationRequest {
+  optional StringList tags = 1;
+}
+message ResumeMemoryOccupationRequest {
+  optional StringList tags = 1;
+}
+message MemoryOccupationResponse {}
+
+// `/freeze_gc`: freeze the Python garbage collector on every DP rank's
+// scheduler, with the launch's `--gc-threshold`.
+message FreezeGcRequest {}
+message FreezeGcResponse {}
+
+// `/pause_generation`. `in_place` holds the scheduler loop with its batches
+// intact; `retract` returns running requests to the waiting queue; `abort`
+// cancels them and is handled by the frontend alone.
+message PauseGenerationRequest {
+  optional string mode = 1 [
+    (sglang.json.v1.field_json).null_policy = NULL_POLICY_RESETS_DEFAULT,
+    (sglang.json.v1.field_json).default_string = "abort"
+  ];
+}
+
+// `/continue_generation`.
+message ContinueGenerationRequest {
+  optional bool torch_empty_cache = 1 [
+    (sglang.json.v1.field_json).null_policy = NULL_POLICY_RESETS_DEFAULT,
+    (sglang.json.v1.field_json).default_bool = true
+  ];
+}
+
+// Python's `{"message": ..., "status": "ok"}` body for pause and continue.
+message GenerationPauseResponse {
+  string message = 1;
+  string status = 2;
+}
+
+// `/pd_role_switch`: flip this instance between prefill and decode at
+// runtime (`--enable-pd-role-switch`). With several DP ranks the frontend
+// first runs a `prepare_only` preflight on every rank.
+message PdRoleSwitchRequest {
+  optional string new_role = 1 [
+    (sglang.json.v1.field_json).null_policy = NULL_POLICY_RESETS_DEFAULT,
+    (sglang.json.v1.field_json).default_string = ""
+  ];
+  optional Int64List decode_cuda_graph_bs = 2;
+  optional double decode_cuda_graph_memory_gb = 3;
+  bool prepare_only = 4;
+}
+
+// Python's `PdRoleSwitchReqOutput`.
+message PdRoleSwitchResponse {
+  bool success = 1;
+  string message = 2;
+  string old_role = 3;
+  string new_role = 4;
+  bool safe_to_restore = 5;
+}
+
+// `/update_weight_version`: relabel the served weights on every DP rank.
+message UpdateWeightVersionRequest {
+  string new_version = 1;
+  optional bool abort_all_requests = 2 [
+    (sglang.json.v1.field_json).null_policy = NULL_POLICY_RESETS_DEFAULT,
+    (sglang.json.v1.field_json).default_bool = true
+  ];
+}
+
+message UpdateWeightVersionResponse {
+  bool success = 1;
+  string message = 2;
+  optional string new_version = 3;
+}

@@ -0,0 +1,45 @@
+// External n-gram corpus management for NGRAM speculative decoding: the
+// frontend tokenizes the documents, every DP rank loads the same chunks.
+syntax = "proto3";
+
+package sglang.api.v1;
+
+import "sglang/api/v1/common.proto";
+import "sglang/json/v1/options.proto";
+
+// `/add_external_corpus`: exactly one of `file_path` (a JSONL file of strings
+// on the server) or `documents`; `token_chunks` is for pre-tokenized input.
+message AddExternalCorpusRequest {
+  // Minted when absent.
+  optional string corpus_id = 1;
+  optional string file_path = 2;
+  optional StringList documents = 3;
+  optional TokenIdsList token_chunks = 4;
+}
+
+message AddExternalCorpusResponse {
+  bool success = 1;
+  string corpus_id = 2;
+  string message = 3;
+  int64 loaded_token_count = 4;
+}
+
+// `/remove_external_corpus`.
+message RemoveExternalCorpusRequest {
+  optional string corpus_id = 1;
+}
+
+message RemoveExternalCorpusResponse {
+  bool success = 1;
+  string message = 2;
+}
+
+// `/list_external_corpora`.
+message ListExternalCorporaRequest {}
+
+message ListExternalCorporaResponse {
+  bool success = 1;
+  // Corpus id to its token count; every rank loads the same set.
+  map<string, int64> corpus_token_counts = 2;
+  string message = 3;
+}

@@ -30,12 +30,12 @@ message MatchedTokens {
 // `FINISH_MATCHED_TOKEN` / `FINISH_MATCHED_STR` / `FINISHED_MATCHED_REGEX` —
 // all three report `type: "stop"`, matching the OpenAI API's value.
 message FinishStop {
-  optional Matched matched = 1;
+  optional Matched matched = 1 [(sglang.json.v1.field_json).emit_null_when_absent = true];
 }

 // `FINISH_LENGTH` — hit `max_new_tokens` (or the context limit).
 message FinishLength {
-  optional uint64 length = 1;
+  optional uint64 length = 1 [(sglang.json.v1.field_json).emit_null_when_absent = true];
 }

 // The `FINISH_ABORT` payload. Python emits all three keys, nulls included.

@@ -0,0 +1,157 @@
+// Ollama-compatible data plane: `/api/chat`, `/api/generate`, `/api/tags`,
+// `/api/show`, as `entrypoints/ollama/protocol.py` declares them. A thin
+// translation onto the native generate path; shared by the HTTP adapter, the
+// gRPC service, and the router.
+syntax = "proto3";
+
+package sglang.api.v1;
+
+import "sglang/api/v1/common.proto";
+import "sglang/json/v1/options.proto";
+
+message OllamaMessage {
+  string role = 1;
+  string content = 2;
+  // Base64 images; accepted and not rendered.
+  optional StringList images = 3;
+}
+
+// The Ollama `options` keys SGLang maps onto its sampling params; any other
+// key is ignored, as Python's `_convert_options_to_sampling_params` does.
+message OllamaOptions {
+  optional double temperature = 1;
+  optional double top_p = 2;
+  optional int64 top_k = 3;
+  // `max_new_tokens`; defaults to 2048 when absent (Ollama answers run long).
+  optional int64 num_predict = 4;
+  optional StringOrList stop = 5;
+  optional double presence_penalty = 6;
+  optional double frequency_penalty = 7;
+  // `sampling_seed`.
+  optional int64 seed = 8;
+}
+
+// `POST /api/chat`.
+message OllamaChatRequest {
+  string model = 1;
+  repeated OllamaMessage messages = 2;
+  optional bool stream = 3 [
+    (sglang.json.v1.field_json).null_policy = NULL_POLICY_RESETS_DEFAULT,
+    (sglang.json.v1.field_json).default_bool = true
+  ];
+  // "json" or a JSON schema; accepted and ignored.
+  optional string format = 4 [(sglang.json.v1.field_json).raw_json = true];
+  optional OllamaOptions options = 5;
+  // Seconds or a duration string; accepted and ignored (no model unloading).
+  optional string keep_alive = 6 [(sglang.json.v1.field_json).raw_json = true];
+  // Bool or "low" | "medium" | "high"; accepted and ignored.
+  optional string think = 7 [(sglang.json.v1.field_json).raw_json = true];
+}
+
+// One `/api/chat` frame. Unary: the whole answer with `done` set and the
+// counters filled. Streamed: a delta per frame, then a `done` frame whose
+// counters are filled (Python leaves them out; the Ollama API fills them).
+// Durations are nanoseconds, as Ollama reports them.
+message OllamaChatResponse {
+  string model = 1;
+  string created_at = 2;
+  OllamaMessage message = 3;
+  bool done = 4;
+  optional string done_reason = 5;
+  optional int64 total_duration = 6;
+  optional int64 load_duration = 7;
+  optional int64 prompt_eval_count = 8;
+  optional int64 prompt_eval_duration = 9;
+  optional int64 eval_count = 10;
+  optional int64 eval_duration = 11;
+}
+
+// `POST /api/generate`. `prompt` is sent raw; `system` is prepended with a
+// blank line. `suffix`, `template`, `context`, `raw`, `format`, `images`,
+// `keep_alive`, and `think` are accepted and ignored, as in Python.
+message OllamaGenerateRequest {
+  string model = 1;
+  string prompt = 2;
+  optional string suffix = 3;
+  optional string system = 4;
+  optional string template = 5;
+  optional Int64List context = 6;
+  optional bool stream = 7 [
+    (sglang.json.v1.field_json).null_policy = NULL_POLICY_RESETS_DEFAULT,
+    (sglang.json.v1.field_json).default_bool = true
+  ];
+  optional bool raw = 8 [
+    (sglang.json.v1.field_json).null_policy = NULL_POLICY_RESETS_DEFAULT,
+    (sglang.json.v1.field_json).default_bool = false
+  ];
+  optional string format = 9 [(sglang.json.v1.field_json).raw_json = true];
+  optional OllamaOptions options = 10;
+  optional string keep_alive = 11 [(sglang.json.v1.field_json).raw_json = true];
+  optional StringList images = 12;
+  optional bool think = 13;
+}
+
+// One `/api/generate` frame; the same unary / streamed contract as
+// OllamaChatResponse. `context` is never filled (no conversation encoding).
+message OllamaGenerateResponse {
+  string model = 1;
+  string created_at = 2;
+  string response = 3;
+  bool done = 4;
