+
+// `PromptTokensDetails`; the multimodal counts appear only when present.
+message OpenAiPromptTokensDetails {
+  int64 cached_tokens = 1;
+  optional int64 image_tokens = 2;
+  optional int64 audio_tokens = 3;
+  optional int64 video_tokens = 4;
+}
+
+message OpenAiCompletionTokensDetails {
+  int64 reasoning_tokens = 1;
