+message OpenAiMultimodalEmbeddingInputList {
+  option (sglang.json.v1.message_json).shape = MESSAGE_SHAPE_BARE_LIST;
+  repeated OpenAiMultimodalEmbeddingInput items = 1;
+}
+
+// `input`: text, texts, token ids, token-id lists, or multimodal items.
+message OpenAiEmbeddingInput {
+  oneof value {
+    option (sglang.json.v1.oneof_json).shape = ONEOF_SHAPE_UNTAGGED;
+    string text = 1;
+    StringList texts = 2;
+    TokenIds ids = 3;
+    TokenIdsList ids_list = 4;
+    OpenAiMultimodalEmbeddingInputList multimodal = 5;
+  }
+}
