+// `POST /v1/embeddings`.
+message OpenAiEmbeddingRequest {
+  OpenAiEmbeddingInput input = 1;
+  optional string model = 2 [
+    (sglang.json.v1.field_json).null_policy = NULL_POLICY_RESETS_DEFAULT,
+    (sglang.json.v1.field_json).default_string = "default"
+  ];
+  // "float" | "base64".
+  optional string encoding_format = 3 [
+    (sglang.json.v1.field_json).null_policy = NULL_POLICY_RESETS_DEFAULT,
+    (sglang.json.v1.field_json).default_string = "float"
+  ];
+  optional int64 dimensions = 4;
+  optional string user = 5;
+  optional StringOrList rid = 6;
+  optional int64 priority = 7;
+  optional OptionalStringOrList lora_path = 8;
+  optional int64 embed_override_token_id = 9;
+  // One `[num_replacements][hidden]` matrix per input, or null to skip it.
+  repeated string embed_overrides = 10 [(sglang.json.v1.field_json).raw_json = true];
+}
+
+// `embedding`: floats, or base64 with `encoding_format` "base64".
+message OpenAiEmbeddingVector {
+  oneof value {
+    option (sglang.json.v1.oneof_json).shape = ONEOF_SHAPE_UNTAGGED;
+    DoubleList floats = 1;
+    string base64 = 2;
+  }
+}
+
+message OpenAiEmbeddingObject {
+  OpenAiEmbeddingVector embedding = 1;
+  int64 index = 2;
+  string object = 3;
+}
+
+message OpenAiEmbeddingResponse {
+  repeated OpenAiEmbeddingObject data = 1;
+  string model = 2;
+  string object = 3;
+  optional OpenAiUsage usage = 4 [(sglang.json.v1.field_json).emit_null_when_absent = true];
+}
