+// ---- Score -----------------------------------------------------------------------
+
+message OpenAiScoreQuery {
+  oneof value {
+    option (sglang.json.v1.oneof_json).shape = ONEOF_SHAPE_UNTAGGED;
+    string text = 1;
+    TokenIds ids = 2;
+  }
+}
+
+message OpenAiScoreItems {
+  oneof value {
+    option (sglang.json.v1.oneof_json).shape = ONEOF_SHAPE_UNTAGGED;
+    string text = 1;
+    StringList texts = 2;
+    TokenIdsList ids_list = 3;
+  }
+}
+
+// `POST /v1/score`.
+message OpenAiScoreRequest {
+  optional OpenAiScoreQuery query = 1;
+  optional OpenAiScoreItems items = 2;
+  optional int64 embed_override_token_id = 3;
+  // `[num_query_embed_overrides][hidden]`.
+  repeated DoubleList query_embed_overrides = 4;
+  // One `[num_item_embed_overrides][hidden]` matrix per item, or null.
+  repeated string item_embed_overrides = 5 [(sglang.json.v1.field_json).raw_json = true];
+  // Shared candidates, or one candidate list per item.
+  optional TokenIdsOrList label_token_ids = 6;
+  bool apply_softmax = 7;
+  optional double temperature = 8 [
+    (sglang.json.v1.field_json).null_policy = NULL_POLICY_RESETS_DEFAULT,
+    (sglang.json.v1.field_json).default_f64 = 1.0
+  ];
+  bool return_token_logprobs = 9;
+  bool item_first = 10;
+  bool return_pooled_hidden_states = 11;
+  // Setwise readout: score at every occurrence of this token instead of the
+  // last position; `scores` is then nested per item.
+  optional string score_extraction_token = 12;
+  optional string model = 13 [
+    (sglang.json.v1.field_json).null_policy = NULL_POLICY_RESETS_DEFAULT,
+    (sglang.json.v1.field_json).default_string = "default"
+  ];
+}
+
+// `[num_rows][num_labels]`.
+message OpenAiScoreMatrix {
+  option (sglang.json.v1.message_json).shape = MESSAGE_SHAPE_BARE_LIST;
+  repeated DoubleList rows = 1;
+}
+
+// One matrix per item (setwise).
+message OpenAiScoreMatrixList {
+  option (sglang.json.v1.message_json).shape = MESSAGE_SHAPE_BARE_LIST;
+  repeated OpenAiScoreMatrix items = 1;
+}
+
+// `scores`: pointwise `[rows][labels]` or setwise `[items][rows][labels]`;
+// the nesting depth tells them apart.
+message OpenAiScores {
+  oneof value {
+    option (sglang.json.v1.oneof_json).shape = ONEOF_SHAPE_UNTAGGED;
+    OpenAiScoreMatrix pointwise = 1;
+    OpenAiScoreMatrixList setwise = 2;
+  }
+}
+
+message OpenAiScoreResponse {
+  OpenAiScores scores = 1;
+  // Parallel to `scores`, rows nullable: `[rows][hidden]` or
+  // `[items][rows][hidden]`.
+  optional string pooled_hidden_states = 2 [
+    (sglang.json.v1.field_json).raw_json = true,
+    (sglang.json.v1.field_json).emit_null_when_absent = true
+  ];
+  repeated DoubleList token_logprobs = 3;
+  string model = 4;
+  optional OpenAiUsage usage = 5 [(sglang.json.v1.field_json).emit_null_when_absent = true];
+  string object = 6;
+}
+
+// ---- Rerank ----------------------------------------------------------------------
+
+// `POST /v1/rerank` (`V1RerankReqInput`): text or multimodal parts.
+message OpenAiRerankRequest {
+  OpenAiChatContent query = 1;
+  repeated OpenAiChatContent documents = 2;
+  optional string instruct = 3;
+  optional int64 top_n = 4;
+  optional bool return_documents = 5 [
+    (sglang.json.v1.field_json).null_policy = NULL_POLICY_RESETS_DEFAULT,
+    (sglang.json.v1.field_json).default_bool = true
+  ];
+}
+
+// One ranked document; the route answers a list of these.
+message OpenAiRerankResult {
+  double score = 1;
+  optional string document = 2;
+  int64 index = 3;
+  optional string meta_info = 4 [
+    (sglang.json.v1.field_json).raw_json = true,
+    (sglang.json.v1.field_json).emit_null_when_absent = true
+  ];
+}
+
+message OpenAiRerankResponse {
+  option (sglang.json.v1.message_json).shape = MESSAGE_SHAPE_BARE_LIST;
+  repeated OpenAiRerankResult items = 1;
+}
+
+// ---- Tokenize / detokenize -------------------------------------------------------
+
+// `POST /v1/tokenize`: exactly one of `prompt` or `messages`; the chat form
