+            Box::pin(async move {
+                let _request = build();
+                tokio::time::sleep(self.delay).await;
+                self.ranks
+                    .iter()
+                    .map(|&rank| RankReply {
+                        rank,
+                        outcome: (self.reply)(rank),
+                    })
