+            message: String,
+        }
+        let (url_a, _) = peer_listener((StatusCode::OK, status_bytes(true, "from 0"))).await;
+        let (url_b, _) = peer_listener((StatusCode::OK, status_bytes(true, "from 2"))).await;
+        let info = DeploymentInfo {
+            rust_server_endpoints: vec![
